/* Offline cover fonts. app.js reads window.COVER_FONT_CSS for the page
   and inlines the same CSS into the PNG export.
   Family names match css/templates.css: QingKe, KuaiLe, MaShan, XiaoWei.
   Full WOFF2 of the SIL OFL 1.1 files from github.com/google/fonts:
     QingKe  ofl/zcoolqingkehuangyou/ZCOOLQingKeHuangYou-Regular.ttf
     KuaiLe  ofl/zcoolkuaile/ZCOOLKuaiLe-Regular.ttf
     MaShan  ofl/mashanzheng/MaShanZheng-Regular.ttf
     XiaoWei ofl/zcoolxiaowei/ZCOOLXiaoWei-Regular.ttf
   License texts: fonts/OFL-*.txt
*/
window.COVER_FONT_CSS = `@font-face{font-family:'QingKe';font-style:normal;font-weight:400;font-display:block;src:url('data:font/woff2;base64,') format('woff2');}
@font-face{font-family:'KuaiLe';font-style:normal;font-weight:400;font-display:block;src:url('data:font/woff2;base64,') format('woff2');}
@font-face{font-family:'MaShan';font-style:normal;font-weight:400;font-display:block;src:url('data:font/woff2;base64,') format('woff2');}
@font-face{font-family:'XiaoWei';font-style:normal;font-weight:400;font-display:block;src:url('data:font/woff2;base64,') format('woff2');}`;
